// Count files from Google Drive scan
const response = $input.first().json;
const timestamp = new Date().toLocaleString('en-US', { timeZone: 'Asia/Ho_Chi_Minh' });

// Check if we have valid response
let fileCount = 0;
let fileList = '';

if (response && response.files && Array.isArray(response.files)) {
  fileCount = response.files.length;

  // Get first 10 files for the list
  const topFiles = response.files.slice(0, 10);
  fileList = topFiles.map((file, index) => 
    `${index + 1}. ${file.name || 'Unnamed'}`
  ).join('\n');

  if (response.files.length > 10) {
    fileList += `\n... and ${response.files.length - 10} more files`;
  }
}

// Build simple email body
const emailBody = `
Google Drive Scan Report
========================

Total files found: ${fileCount} files

${fileList ? 'Recent files:\n' + fileList : 'No files found'}

Last scan: ${timestamp}

---
This is an automated test scan from your n8n workflow.
`;

return [{
  json: {
    fileCount: fileCount,
    timestamp: timestamp,
    emailBody: emailBody,
    emailSubject: `📊 Drive Scan: ${fileCount} files found`
  }
}];
